void mainImage( out vec4 fragColor, in vec2 fragCoord )
{   
    // limit rendering to the lower left of the screen
    const float size = 258.0;    
    if (fragCoord.x > size || fragCoord.y > size)
    {
        fragColor = vec4(0.0);
        return;
    }

    // calculate uv
	vec2 uv = fragCoord/size;

    // center uv to prep for rotation transformation
    vec2 center= vec2(0.5);
    uv -= center;

    // apply spin using 2D rotation matrix
    float spinSpeed = 1.0; // adjustable spin speed
    float angle = iTime * spinSpeed;
    mat2 spin2D = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
    uv *= spin2D;

    // translate uv back to original position
    uv += center;

    // sample texture (can remove vec2 shift from uv for stationary spin)
    fragColor = texture(iChannel0,uv+vec2(iTime, 0.0)); 
}
